import{Gi as e,Wi as t,Yi as n,la as r,oi as i,pt as a}from"./shared-B3uF1DwJ.js";var o={updated:`17 ноября 2026 г.`,operator:{contactEmail:`info@game-scout.ru`,name:`Литвинов А. И., самозанятый (налог на профессиональный доход)`,fullName:`Литвинов Андрей Игоревич, самозанятый (налог на профессиональный доход)`,inn:`622907774792`,address:``},privacy:JSON.parse(`{"path":"/privacy","title":"Политика обработки персональных данных","description":"Какие данные GameScout получает при входе и регистрации, где их хранит, зачем использует и как их удалить.","sections":[{"heading":"1. Кто обрабатывает данные","paragraphs":["Оператор персональных данных — владелец сервиса GameScout (game-scout.ru), далее «мы». Реквизиты оператора и контакт для запросов указаны в конце этой страницы.","Политика относится только к сайту game-scout.ru и его личному кабинету. Публичный каталог серверов можно смотреть без входа и без передачи нам личных данных."]},{"heading":"2. Какие данные мы получаем","paragraphs":["Только те данные, которые нужны, чтобы вы могли войти, голосовать и управлять своими серверами:"],"list":["Адрес электронной почты и имя в сервисе — если вы регистрируетесь по почте или привязываете почту к аккаунту.","Пароль. Мы храним только стойкий необратимый хеш scrypt с индивидуальной солью, сам пароль мы не видим и не можем восстановить.","При входе через Google, Discord или Telegram — идентификатор вашего аккаунта у провайдера, отображаемое имя и адрес аватара. Пароль от аккаунта провайдера нам не передаётся.","Служебные данные безопасности: короткоживущий идентификатор сессии (cookie), а также хеши IP-адреса и устройства для защиты от накруток и подбора паролей. Для защиты от накрутки хранится обезличенный хеш характеристик браузера (отрисовка картинки, видеокарта, часовой пояс, язык, размер экрана, число ядер процессора); по нему нельзя восстановить сами характеристики или узнать, кто вы. Сами IP-адреса мы не храним в открытом виде. Проверку «вы не робот» выполняет Cloudflare Turnstile: при голосовании и регистрации браузер обращается к challenges.cloudflare.com.","Данные, которые вы вводите сами: заявки на подтверждение прав на сервер, обращения правообладателей, сообщения в поддержку, голоса и их история."]},{"heading":"3. Зачем мы это используем","list":["Чтобы создать и защитить ваш аккаунт и отправлять вам письма с подтверждением.","Чтобы учитывать голоса, награды и заявки владельцев и защищать рейтинг от накрутки.","Чтобы рассматривать обращения правообладателей и запросы в поддержку.","Чтобы выполнять требования закона."],"paragraphs":["Мы не продаём данные, не показываем рекламу на основе ваших данных и не используем рекламные cookie. Для подсчёта посещаемости используется Яндекс Метрика, подробности и способ отключения — в разделе «Файлы cookie»."]},{"heading":"4. Где хранятся данные","paragraphs":["Аккаунты, сессии входа, голоса, заявки владельцев и данные модерации хранятся в базе данных сервиса Cloudflare (D1); серверы Cloudflare могут находиться за пределами Российской Федерации. Данные Coins и платежей хранятся в базе PostgreSQL на нашем сервере в Москве. Резервные копии шифруются перед сохранением.","Письма с кодами и ссылками сейчас отправляются через почтовую службу Google (Gmail): в этот момент адрес получателя обрабатывается на серверах Google. Если мы сменим почтовую службу, эта страница будет обновлена.","Публичные данные каталога (карточки серверов без личных данных) могут отдаваться через сервисы Cloudflare."]},{"heading":"5. Файлы cookie","list":["gs_private_session — идентификатор входа в аккаунт, действует до 7 дней или до выхода. Нужен для работы кабинета.","gs_private_oauth — временная метка защиты при входе через Google или Discord, действует до 10 минут.","gs_ref — запоминает, по чьей приглашающей ссылке вы пришли, действует до 30 дней; нужна, чтобы учесть приглашение при регистрации.","_ym_uid, _ym_d, _ym_isad и похожие с префиксом _ym_ — cookie Яндекс Метрики, срок до одного года. Нужны только для подсчёта визитов; ставятся, если вы не отключили аналитику (как отключить, написано ниже)."],"paragraphs":["Других cookie сайт не устанавливает. Отказ от cookie входа сделает вход в аккаунт невозможным; отказ от cookie Метрики на работу сайта не влияет.","В локальном хранилище браузера сохраняются только настройки интерфейса и список избранного. В локальном хранилище браузера также лежит случайная метка устройства для защиты голосования от накрутки; её можно удалить, очистив данные сайта. Эти данные не используются для рекламы.","Для подсчёта визитов сайт использует Яндекс Метрику (на запасном адресе — Cloudflare Web Analytics). Метрика записывает cookie с префиксом _ym_, передаёт в Яндекс адреса посещённых страниц, источник перехода, сведения об устройстве и браузере и ваш IP-адрес; мы используем её только для подсчёта посещаемости и не используем для рекламы. Вебвизор, карта кликов и аналитика форм отключены, содержимое форм и введённые данные в Метрику не передаются. Мы видим сводные числа: страницы, источники переходов, устройства, регионы и скорость загрузки. Отключить подсчёт на этом устройстве можно, открыв один раз адрес главной страницы с добавкой ?noanalytics=1 (например, game-scout.ru/?noanalytics=1), либо блокировщиком трекеров; на работу сайта это не влияет.","Владельцам серверов мы показываем обезличенную статистику карточки: сколько раз её открыли и сколько раз перешли на сайт или нажали «Играть». Браузер сообщает только номер карточки и тип действия; адрес, устройство и источник перехода не передаются и не хранятся. Чтобы не считать одно действие дважды, в хранилище текущей вкладки ставится отметка, которая удаляется при её закрытии. Сводные числа хранятся 120 дней."]},{"heading":"6. Как долго мы храним данные","paragraphs":["Данные аккаунта хранятся, пока аккаунт существует. Ссылки подтверждения действуют 20 минут, OAuth-state — до 10 минут, сессии — до 7 дней. Просроченные технические записи удаляются автоматически; окна ограничения запросов старше 24 часов удаляются. После удаления аккаунта мы удаляем или обезличиваем персональные данные; записи журнала безопасности могут храниться дольше в обезличенном виде, если это необходимо для защиты сервиса и требований закона."]},{"heading":"7. Кому мы передаём данные","paragraphs":["Мы передаём данные только тем, кто нужен для работы сервиса: хостинг и базы данных (Cloudflare и наш сервер в Москве, см. раздел 4), почтовая отправка (см. раздел 4), счётчик посещаемости (Яндекс Метрика), а при входе через Google, Discord или Telegram — обмен данными с выбранным вами провайдером. Другим лицам данные не передаются, кроме случаев, прямо предусмотренных законом."]},{"heading":"8. Ваши права","paragraphs":["Вы можете запросить информацию о том, какие данные мы о вас храним, потребовать их исправить, ограничить обработку, удалить аккаунт и данные или отозвать согласие на обработку. Для этого напишите на адрес, указанный ниже: мы ответим в срок, установленный законом (до 10 рабочих дней).","Если вы считаете, что мы нарушаем закон о персональных данных, вы вправе обратиться в Роскомнадзор."]},{"heading":"9. Согласие","paragraphs":["Регистрируясь или входя в аккаунт, вы соглашаетесь с этой политикой и с обработкой перечисленных выше данных для указанных целей. Согласие можно отозвать в любой момент, удалив аккаунт или написав нам."]},{"heading":"10. Изменения","paragraphs":["Мы можем обновлять политику. Актуальная версия всегда доступна по адресу game-scout.ru/privacy, дата последнего обновления указана на странице."]}]}`),terms:{path:`/terms`,title:`Пользовательское соглашение`,description:`Правила использования GameScout: аккаунт, голосование, карточки серверов и ответственность сторон.`,sections:[{heading:`1. О сервисе`,paragraphs:[`GameScout — независимый каталог игровых серверов (Lineage 2, Minecraft, GTA RP) с рейтингами, голосованием игроков и кабинетом владельца. Сервис не связан с издателями игр и с владельцами перечисленных серверов, если это не указано отдельно.`,`Используя сайт, вы принимаете это соглашение и политику обработки персональных данных на странице /privacy.`]},{heading:`2. Аккаунт`,list:[`Аккаунт создаётся по почте или через Google или Discord. Вы отвечаете за сохранность доступа к своей почте и к аккаунту у провайдера.`,`Один человек — один аккаунт. Передавать аккаунт другим лицам нельзя.`,`Мы вправе ограничить или заблокировать аккаунт при нарушении правил, в том числе при попытках накрутки голосов.`]},{heading:`3. Голосование и рейтинги`,list:[`В сутки у каждого аккаунта три голоса: за один сервер, один клан или одну семью и одно медиа; следующий голос в категории открывается через 24 часа после предыдущего голоса в ней.`,`Голоса должны отражать ваше собственное мнение об игровом сервере. Накрутка, боты, обмен голосами, использование нескольких аккаунтов и любые попытки обойти защиту запрещены.`,`Мы вправе не засчитывать или отменять голоса, которые сочтём сомнительными, и корректировать рейтинги.`,`Онлайн со статусом VERIFIED измеряет GameScout, остальные числа подписаны источником. Данные могут содержать неточности.`]},{heading:`4. Владельцам серверов`,list:[`Заявку на подтверждение прав на сервер проверяет администратор. Присылайте только ту информацию, которая действительно подтверждает ваши права. Пароли и секретные ключи не отправляйте.`,`Вы отвечаете за содержание своей карточки: описание, ссылки и материалы не должны нарушать чужие права и закон.`,`Мы вправе отклонить заявку, скрыть или удалить материал, если он нарушает правила или права третьих лиц.`]},{heading:`5. Содержание и права третьих лиц`,paragraphs:[`Названия игр и серверов, логотипы и иные обозначения принадлежат их владельцам. Если вы правообладатель и считаете, что материал на нашем сайте нарушает ваши права, отправьте обращение через страницу /copyright: мы рассмотрим его и при необходимости уточним детали.`]},{heading:`6. Запрещено`,list:[`Мешать работе сайта, автоматизированно собирать данные в объёме, создающем нагрузку, искать и использовать уязвимости.`,`Размещать незаконный контент, вводить в заблуждение относительно сервера или выдавать себя за другое лицо.`,`Пытаться получить доступ к чужим аккаунтам или к данным других пользователей.`]},{heading:`7. Ответственность`,paragraphs:[`Сервис предоставляется «как есть». Мы стремимся к точности данных, но не гарантируем их полноту и бесперебойную работу сайта. Мы не отвечаем за содержание сторонних сайтов и игровых серверов, на которые ведут ссылки, и за решения, принятые на основании каталога.`,`Наша ответственность перед пользователем ограничивается прямым действительным ущербом и не включает упущенную выгоду, если иное не установлено законом.`]},{heading:`8. Изменения и право`,paragraphs:[`Мы можем изменять соглашение; новая редакция действует с момента публикации на этой странице. Продолжая пользоваться сайтом, вы принимаете изменения.`,`К отношениям сторон применяется право Российской Федерации. Спорные вопросы стороны стараются решать переговорами; претензии направляйте на адрес, указанный ниже.`]}]},offer:JSON.parse(`{"path":"/offer","title":"Публичная оферта о приобретении GS Coins","description":"Условия покупки внутренних единиц GS Coins: что это такое, цена и оплата, возврат, ответственность сторон.","sections":[{"heading":"1. Общие положения","paragraphs":["Настоящий документ — публичная оферта (ст. 435 и 437 Гражданского кодекса РФ) о приобретении внутренних единиц GS Coins сервиса GameScout (game-scout.ru). Исполнитель — самозанятый, применяющий налог на профессиональный доход; сведения о нём (ФИО и ИНН) указаны в конце этой страницы.","Акцептом оферты считается оплата GS Coins. С момента оплаты договор считается заключённым на условиях ниже. Покупать GS Coins может дееспособный пользователь сайта, вошедший в свой аккаунт."]},{"heading":"2. Что такое GS Coin","list":["GS Coin — внутренняя единица учёта сервиса GameScout. Это не деньги, не электронные денежные средства, не ценная бумага и не цифровая валюта.","Условный номинал, по которому рассчитывается цена: 1 GS Coin = 50 ₽. Вне сервиса GS Coins ничего не стоят.","GS Coins нельзя вывести, продать, передать другому пользователю или обменять на деньги.","Баланс виден в личном кабинете, каждая операция (покупка, списание, возврат) записывается в журнал."]},{"heading":"3. Для чего используются GS Coins","list":["Поддержка выбранного игрового сервера в рейтинге «Поддержка» и другие функции, которые будут описаны на сайте отдельно.","Поддержка не влияет на рейтинг «Голоса»: он строится только по голосам игроков.","Исполнитель не продаёт места в рейтингах и не гарантирует конкретное место сервера."]},{"heading":"4. Цена, заказ и оплата","paragraphs":["Цена: 1 GS Coin = 50 ₽, скидок и наценок нет. Примеры: 10 GS Coins — 500 ₽, 50 GS Coins — 2 500 ₽, 100 GS Coins — 5 000 ₽. Можно купить любое целое количество от 1 до 10 000 GS Coins за один заказ. НДС не применяется: Исполнитель — самозанятый.","Количество GS Coins и цена в рублях показываются перед оплатой. Оплата проходит через платёжный сервис способами, которые доступны на его платёжной странице; данные банковской карты Исполнителю не передаются, их обрабатывает платёжный сервис.","GS Coins зачисляются на баланс после подтверждения платежа, обычно в течение нескольких минут. Чек самозанятого направляется на адрес электронной почты аккаунта или формируется в приложении «Мой налог» и доступен по ссылке."],"list":["Порядок заказа: войдите в аккаунт, подтвердите адрес электронной почты, откройте раздел «Кошелёк» и нажмите «Пополнить баланс».","Укажите количество GS Coins, проверьте сумму в рублях и нажмите кнопку перехода к оплате.","Оплатите заказ на странице платёжного сервиса. Заказ считается оплаченным после подтверждения платежа платёжным сервисом.","Срок исполнения заказа: зачисление GS Coins на баланс обычно в течение нескольких минут после подтверждения платежа, не позднее 3 рабочих дней."]},{"heading":"4а. Как оказывается услуга","paragraphs":["Услуга цифровая: физической доставки нет. Исполнитель зачисляет GS Coins на баланс вашего аккаунта на сайте game-scout.ru, после чего вы сами решаете, на какой игровой сервер направить поддержку. Зачисленные GS Coins доступны сразу, срок их использования не ограничен, пока существует аккаунт и сервис.","Поддержка сервера оказывается мгновенно: после подтверждения списания GS Coins засчитываются выбранному серверу в рейтинге «Поддержка», результат виден на сайте. Исполнитель не гарантирует конкретное место сервера в рейтинге."]},{"heading":"5. Возврат","paragraphs":["Ниже прямо перечислено, когда деньги возвращаются и когда нет. Эти условия не ограничивают прав потребителя, которые закон не позволяет ограничить."],"list":["Возвращаем полностью, если: (а) платёж списан дважды или более раз за одну покупку; (б) платёж прошёл, а GS Coins не зачислены или зачислены в меньшем количестве, чем оплачено, и это не исправлено в течение 3 рабочих дней; (в) поддержка сервера, оплаченная GS Coins, не была засчитана или не показана в рейтинге по вине сервиса.","Неиспользованные GS Coins возвращаем по вашему заявлению, если вы отказываетесь от услуги (ст. 32 Закона «О защите прав потребителей»): возвращается полная оплаченная стоимость неиспользованных GS Coins, комиссия платёжного сервиса или банка из суммы возврата не вычитается.","Не возвращаем GS Coins, уже потраченные на поддержку сервера и засчитанные в рейтинге «Поддержка»: услуга оказана надлежащим образом, а ее результат вы видите на сайте. Исключение — случай (в) выше.","Не возвращаем деньги при блокировке аккаунта за накрутку, мошенничество или использование чужих платёжных средств, а также за платежи, оспоренные плательщиком в банке, пока спор не решён в вашу пользу.","Порядок возврата. Заявление подаётся письменно, одним письмом на адрес электронной почты из раздела «Оператор и контакты», только с адреса электронной почты, привязанного к аккаунту. В заявлении укажите: имя аккаунта, дату и время платежа, сумму, номер заказа или чека из письма об оплате, причину возврата и реквизиты оплаты (последние 4 цифры карты или иной способ).","Мы проверяем заявление по журналу операций аккаунта и данным платёжного сервиса: был ли платёж, сколько GS Coins зачислено и сколько из них использовано. Для этого мы вправе запросить подтверждение, что аккаунтом и платёжным средством владеете вы (например, ответ на проверочное письмо). Заявление без этих данных принимается после того, как вы их дополните; срок рассмотрения считается с получения всех данных.","Срок: ответ на заявление — в течение 3 рабочих дней, решение и возврат — в течение 10 дней со дня получения полного заявления (общий срок не дольше установленного законом). Возврат идёт только тем же способом и на те же реквизиты, которыми была оплата; на другие реквизиты и наличными возврат не производится.","Если заявление отклонено, мы сообщаем причину; отказ можно оспорить, направив претензию на тот же адрес электронной почты."]},{"heading":"6. Блокировка аккаунта","paragraphs":["При нарушении правил сайта (накрутка, мошенничество, использование чужих платёжных средств) Исполнитель вправе ограничить аккаунт. Оставшиеся GS Coins возвращаются, кроме случаев мошенничества и оспоренных платежей."]},{"heading":"7. Ответственность","paragraphs":["Сервис предоставляется «как есть». В пределах, допускаемых законом, ответственность Исполнителя ограничена суммой платежа за соответствующие GS Coins."]},{"heading":"8. Персональные данные","paragraphs":["Данные обрабатываются по политике обработки персональных данных на странице /privacy."]},{"heading":"9. Споры и изменения","paragraphs":["Претензии принимаются на адрес электронной почты из раздела «Оператор и контакты»; ответ — в течение 10 дней. Если спор не решён, он рассматривается по законодательству Российской Федерации, при этом права потребителя на выбор подсудности сохраняются.","Исполнитель вправе менять оферту; для уже купленных GS Coins действует редакция на момент покупки."]}],"links":[{"label":"Правила GS Coins","to":"/coins-rules"},{"label":"Политика обработки данных","to":"/privacy"}]}`),coinsRules:{path:`/coins-rules`,title:`Правила GS Coins и Поддержки`,description:`Как работают GS Coins и поддержка серверов: что можно, что нельзя, как возвращаются неиспользованные единицы.`,sections:[{heading:`Коротко`,list:[`GS Coins покупаются, а не зарабатываются, и не выводятся. Баланс и журнал операций доступны в кабинете.`,`Поддержка сервера: вы выбираете сервер и количество GS Coins, до списания видите, какое место получится в рейтинге «Поддержка».`,`Рейтинг «Голоса» строится только по голосам игроков, поддержка на него не влияет.`,`Мы не продаём места в рейтингах и не обещаем результат.`]},{heading:`Публичное имя в списке поддержавших`,paragraphs:[`Показывается то имя, которое вы выберете. Неподходящие имена заменяются на «Анонимно»; поддержка при этом засчитывается.`]},{heading:`Возврат`,list:[`Возвращаем: двойное списание; платёж прошёл, а GS Coins не зачислены или зачислены не полностью; поддержка не засчитана по вине сервиса.`,`Возвращаем неиспользованные GS Coins по заявлению в полной оплаченной сумме, комиссия платёжного сервиса из неё не вычитается.`,`Не возвращаем GS Coins, потраченные на поддержку, если поддержка засчитана и видна в рейтинге.`,`Не возвращаем при блокировке за накрутку и мошенничество и при оспоренных платежах до решения спора.`],paragraphs:[`Заявление подаётся письмом с почты аккаунта: номер заказа или чека, дата, сумма и причина. Рассматриваем в течение 10 дней, возвращаем на те же реквизиты. Полные условия — в публичной оферте.`]}],links:[{label:`Публичная оферта`,to:`/offer`},{label:`Пользовательское соглашение`,to:`/terms`}]}},s={updated:`29 октября 2026 г.`,path:`/about`,title:`О проекте и методика`,description:`Что такое GameScout, откуда берутся карточки серверов, как проверяется и подписывается онлайн и как считается общий топ.`,sections:[{heading:`Что такое GameScout`,paragraphs:[`GameScout (gamescout.online) — каталог игровых серверов Lineage 2, Minecraft и GTA RP (FiveM и RAGE:MP). В карточке сервера собраны версия или хроника, рейты или режим, регион, дата открытия, ссылки проекта и онлайн с указанием источника.`,`Смотреть каталог и добавлять сервер можно бесплатно. Главное правило проекта: каждое число на сайте подписано источником и временем, а то, что нельзя подтвердить, не выдаётся за факт.`]},{heading:`Откуда берутся карточки`,paragraphs:[`Карточки собраны из открытых источников: официальных сайтов, страниц и сообществ проектов. Источник и дата сверки указаны на странице сервера.`,`В публичный каталог попадают только подтверждённые характеристики. Если поле проверить не удалось, оно остаётся пустым с пометкой «не указано» — мы не заполняем его догадками.`]},{heading:`Как проверяется онлайн`,paragraphs:[`Онлайн ищется по цепочке источников: сначала собственная проверка GameScout, затем счётчик, который публикует сам проект, затем сторонний мониторинг. Рядом с числом всегда указаны статус, источник и время обновления; устаревшее число не показывается как текущее.`],list:[`«Проверено GameScout» (VERIFIED) — игроков посчитали мы сами: по списку игроков с адреса самого сервера или через API и агент владельца. Число, которое сервер просто сообщает о себе, так не помечается.`,`LIVE — сервер отвечает на нашу проверку, но число игроков он сообщает о себе сам (как Minecraft) или не сообщает вовсе (как Lineage 2), поэтому подтвердить его нельзя.`,`«По данным владельца» — счётчик, который проект публикует на своём сайте или в API.`,`Внешний мониторинг — число стороннего сервиса (например, mcsrvstat.us или BattleMetrics) с его названием. Такое число никогда не помечается как проверенное.`,`OFFLINE — только при основании: источник сообщает, что сервер выключен, или наша проверка не прошла дважды, а спросить больше некого.`,`Если не ответил ни один источник, онлайн неизвестен — это не ноль и не OFFLINE.`,`«Аномалия» — по адресу сервера отвечает другой проект (например, адрес передали другому серверу); такие данные не привязываются к карточке до перепроверки.`]},{heading:`Особенности игр`,list:[`Minecraft: сервер отвечает на стандартный запрос статуса, поэтому его доступность и заявленный онлайн видны напрямую.`,`GTA RP (FiveM): точный онлайн засчитывается только по списку игроков с собственного адреса сервера.`,`Lineage 2: открытого способа узнать число игроков нет. Проверить можно доступность сервера входа; точный проверенный онлайн возможен только через API или агент владельца.`]},{heading:`Как считается общий топ`,paragraphs:[`Голоса игроков, поддержка и свежий онлайн дают по одной трети общего показателя. Значения сравниваются внутри одной игры; отсутствующие данные не добавляют баллов.`,`Отдельный рейтинг «Голоса» учитывает только голоса игроков. Поддержка за GS Coins показывается отдельно и не добавляет голосов.`]},{heading:`Чего мы не делаем`,list:[`Не придумываем онлайн и не округляем его в большую сторону.`,`Не пишем отзывы и голоса от имени игроков.`,`Не обходим защиту от ботов на чужих сайтах: если источник закрыт, число не показывается.`,`Не объединяем аккаунты по адресу почты от Google или Discord без явного действия пользователя.`]},{heading:`Владельцам серверов`,paragraphs:[`Сервер можно добавить через форму каталога. Права на карточку подтверждаются DNS-записью, файлом на сайте проекта, через Discord или ручной проверкой администратора. Подключение API или агента позволяет показывать проверенный онлайн.`]},{heading:`Нашли ошибку?`,paragraphs:[`Если в карточке неверные данные, напишите нам на почту ниже и укажите ссылку на страницу сервера. Претензии правообладателей принимаются через отдельную форму.`]}],links:[{label:`Каталог серверов`,to:`/catalog`},{label:`Владельцам серверов`,to:`/owners`},{label:`Правообладателям`,to:`/copyright`}]},c={updated:`17 November 2026`,operator:{contactEmail:`info@game-scout.ru`,name:`Litvinov A. I., self-employed (professional income tax)`,fullName:`Andrey Igorevich Litvinov, self-employed (professional income tax)`,inn:`622907774792`,address:``},privacy:{path:`/privacy`,title:`Personal Data Processing Policy`,description:`What data GameScout receives when you sign in and register, where it is stored, why it is used and how to delete it.`,sections:[{heading:`1. Who processes the data`,paragraphs:[`The personal data operator is the owner of the GameScout service (game-scout.ru), hereinafter "we". The operator's details and the contact for requests are given at the end of this page.`,`This policy applies only to the game-scout.ru site and its personal account. The public server catalog can be viewed without signing in and without giving us any personal data.`]},{heading:`2. What data we receive`,paragraphs:[`Only the data needed for you to sign in, vote and manage your servers:`],list:[`Email address and a name in the service, if you register by email or link an email to your account.`,`Password. We store only a strong irreversible scrypt hash with an individual salt; we do not see the password itself and cannot recover it.`,`When signing in with Google, Discord or Telegram: your account identifier at the provider, the display name and the avatar address. The password of the provider account is not passed to us.`,`Security service data: a short-lived session identifier (cookie), as well as hashes of the IP address and the device to protect against vote manipulation and password guessing. To protect against manipulation, an anonymized hash of browser characteristics is stored (image rendering, graphics card, time zone, language, screen size, number of processor cores); the characteristics themselves cannot be recovered from it, and it cannot tell who you are. We do not store IP addresses in plain form. The "you are not a robot" check is performed by Cloudflare Turnstile: when voting and registering, the browser contacts challenges.cloudflare.com.`,`Data you enter yourself: applications to confirm ownership of a server, rights holder claims, messages to support, votes and their history.`]},{heading:`3. Why we use it`,list:[`To create and protect your account and to send you confirmation emails.`,`To count votes, rewards and owner applications and to protect the ranking from manipulation.`,`To consider rights holder claims and support requests.`,`To comply with the law.`],paragraphs:[`We do not sell data, do not show advertising based on your data and do not use advertising cookies. Yandex Metrica is used to count visits; details and how to opt out are in the "Cookies" section.`]},{heading:`4. Where the data is stored`,paragraphs:[`Accounts, sign-in sessions, votes, owner applications and moderation data are stored in the Cloudflare database service (D1); Cloudflare servers may be located outside the Russian Federation. Coins and payment data are stored in a PostgreSQL database on our server in Moscow. Backups are encrypted before they are saved.`,`Emails with codes and links are currently sent through the Google mail service (Gmail): at that moment the recipient's address is processed on Google servers. If we change the mail service, this page will be updated.`,`Public catalog data (server cards without personal data) may be served through Cloudflare services.`]},{heading:`5. Cookies`,list:[`gs_private_session: the account sign-in identifier, valid for up to 7 days or until you sign out. Needed for the personal account to work.`,`gs_private_oauth: a temporary protection mark when signing in with Google or Discord, valid for up to 10 minutes.`,`gs_ref: remembers whose invitation link you came from, valid for up to 30 days; needed to credit the invitation at registration.`,`_ym_uid, _ym_d, _ym_isad and similar with the _ym_ prefix: Yandex Metrica cookies, lifetime up to one year. They are used only to count visits; they are set if you have not disabled analytics (how to disable it is described below).`],paragraphs:[`The site sets no other cookies. Refusing the sign-in cookie will make signing in to an account impossible; refusing the Metrica cookies does not affect how the site works.`,`Only interface settings and the favorites list are saved in the browser's local storage. A random device mark that protects voting from manipulation is also kept in the browser's local storage; you can delete it by clearing the site data. This data is not used for advertising.`,`To count visits the site uses Yandex Metrica (on the reserve address, Cloudflare Web Analytics). Metrica writes a cookie with the _ym_ prefix, passes to Yandex the addresses of visited pages, the referrer, information about the device and browser and your IP address; we use it only to count traffic and do not use it for advertising. Webvisor, the click map and form analytics are disabled, and form contents and entered data are not passed to Metrica. We see summary numbers: pages, referrers, devices, regions and load speed. You can disable counting on this device by opening the home page address once with ?noanalytics=1 added (for example, game-scout.ru/?noanalytics=1), or with a tracker blocker; this does not affect how the site works.`,`To server owners we show anonymized statistics of the card: how many times it was opened and how many times visitors went to the site or pressed "Play". The browser reports only the card number and the type of action; the address, device and referrer are not passed or stored. To avoid counting one action twice, a mark is placed in the storage of the current tab and is removed when it is closed. Summary numbers are stored for 120 days.`]},{heading:`6. How long we keep the data`,paragraphs:[`Account data is kept while the account exists. Confirmation links are valid for 20 minutes, the OAuth state for up to 10 minutes, sessions for up to 7 days. Expired technical records are deleted automatically; rate-limit windows older than 24 hours are deleted. After an account is deleted we delete or anonymize personal data; security log records may be kept longer in anonymized form if necessary to protect the service and to meet legal requirements.`]},{heading:`7. Who we pass data to`,paragraphs:[`We pass data only to those needed for the service to work: hosting and databases (Cloudflare and our server in Moscow, see section 4), mail delivery (see section 4), the visit counter (Yandex Metrica), and, when signing in with Google, Discord or Telegram, the exchange of data with the provider you choose. Data is not passed to other parties except in cases directly provided for by law.`]},{heading:`8. Your rights`,paragraphs:[`You can request information about what data we store about you, demand that it be corrected, restrict processing, delete your account and data, or withdraw consent to processing. To do so, write to the address given below: we will reply within the period set by law (up to 10 business days).`,`If you believe that we violate the personal data law, you have the right to contact Roskomnadzor.`]},{heading:`9. Consent`,paragraphs:[`By registering or signing in to an account, you agree to this policy and to the processing of the data listed above for the stated purposes. Consent can be withdrawn at any time by deleting your account or by writing to us.`]},{heading:`10. Changes`,paragraphs:[`We may update the policy. The current version is always available at game-scout.ru/privacy, and the date of the last update is shown on the page.`]}]},terms:{path:`/terms`,title:`User Agreement`,description:`Rules of using GameScout: account, voting, server cards and the responsibility of the parties.`,sections:[{heading:`1. About the service`,paragraphs:[`GameScout is an independent catalog of game servers (Lineage 2, Minecraft, GTA RP) with rankings, player voting and an owner's dashboard. The service is not affiliated with game publishers or with the owners of the listed servers unless stated separately.`,`By using the site you accept this agreement and the personal data processing policy on the /privacy page.`]},{heading:`2. Account`,list:[`An account is created by email or through Google or Discord. You are responsible for keeping your access to your email and to your account at the provider safe.`,`One person, one account. An account may not be passed to other persons.`,`We may restrict or block an account for violating the rules, including attempts to manipulate votes.`]},{heading:`3. Voting and rankings`,list:[`Each account has three votes per day: for one server, one clan or one family, and one media; the next vote in a category opens 24 hours after the previous vote in it.`,`Votes must reflect your own opinion of a game server. Manipulation, bots, vote trading, using several accounts and any attempts to bypass protection are prohibited.`,`We may not count or may cancel votes that we consider doubtful, and adjust rankings.`,`Online with the VERIFIED status is measured by GameScout; other numbers are labelled with their source. Data may contain inaccuracies.`]},{heading:`4. For server owners`,list:[`An application to confirm ownership of a server is checked by an administrator. Send only information that really confirms your rights. Do not send passwords or secret keys.`,`You are responsible for the content of your card: descriptions, links and materials must not violate the rights of others or the law.`,`We may reject an application, hide or delete material if it violates the rules or the rights of third parties.`]},{heading:`5. Content and rights of third parties`,paragraphs:[`The names of games and servers, logos and other designations belong to their owners. If you are a rights holder and believe that material on our site violates your rights, send a claim through the /copyright page: we will consider it and, if necessary, ask for details.`]},{heading:`6. Prohibited`,list:[`Interfering with the operation of the site, collecting data automatically in a volume that creates load, searching for and exploiting vulnerabilities.`,`Posting illegal content, misleading others about a server or impersonating another person.`,`Attempting to gain access to other people's accounts or to the data of other users.`]},{heading:`7. Liability`,paragraphs:[`The service is provided "as is". We strive for accurate data but do not guarantee its completeness or uninterrupted operation of the site. We are not responsible for the content of third-party sites and game servers that the links lead to, or for decisions made on the basis of the catalog.`,`Our liability to the user is limited to direct actual damage and does not include lost profit, unless the law provides otherwise.`]},{heading:`8. Changes and governing law`,paragraphs:[`We may change the agreement; the new version takes effect from its publication on this page. By continuing to use the site you accept the changes.`,`The law of the Russian Federation applies to the relations of the parties. The parties try to resolve disputes through negotiation; send claims to the address given below.`]}]},offer:{path:`/offer`,title:`Public Offer for the Purchase of GS Coins`,description:`Terms of purchasing the internal GS Coins units: what they are, price and payment, refunds, responsibility of the parties.`,sections:[{heading:`1. General provisions`,paragraphs:[`This document is a public offer (Articles 435 and 437 of the Civil Code of the Russian Federation) for the purchase of the internal GS Coins units of the GameScout service (game-scout.ru). The Contractor is a self-employed person applying the professional income tax; information about them (full name and taxpayer ID) is given at the end of this page.`,`Payment for GS Coins is the acceptance of the offer. From the moment of payment the contract is considered concluded on the terms below. GS Coins can be purchased by a legally capable user of the site who is signed in to their account.`]},{heading:`2. What a GS Coin is`,list:[`A GS Coin is an internal accounting unit of the GameScout service. It is not money, not electronic money, not a security and not a digital currency.`,`The conventional face value used to calculate the price: 1 GS Coin = 50 RUB. Outside the service GS Coins are worth nothing.`,`GS Coins cannot be withdrawn, sold, passed to another user or exchanged for money.`,`The balance is visible in the personal account, and every operation (purchase, debit, refund) is recorded in the journal.`]},{heading:`3. What GS Coins are used for`,list:[`Supporting a chosen game server in the "Support" ranking and other functions that will be described separately on the site.`,`Support does not affect the "Votes" ranking: it is built only from player votes.`,`The Contractor does not sell places in rankings and does not guarantee any particular place for a server.`]},{heading:`4. Price, ordering and payment`,paragraphs:[`Price: 1 GS Coin = 50 RUB, with no discounts or markups. Examples: 10 GS Coins = 500 RUB, 50 GS Coins = 2,500 RUB, 100 GS Coins = 5,000 RUB. You can buy any whole number from 1 to 10,000 GS Coins per order. VAT is not charged: the Contractor is self-employed.`,`The number of GS Coins and the price in rubles are shown before payment. Payment goes through the payment service by the methods available on its payment page; bank card data is not passed to the Contractor and is processed by the payment service.`,`GS Coins are credited to the balance after the payment is confirmed, usually within a few minutes. The self-employed receipt is sent to the account's email address or generated in the "My Tax" app and is available by link.`],list:[`How to order: sign in, confirm your email address, open the Wallet section and press "Top up balance".`,`Enter the number of GS Coins, check the amount in rubles and press the button to go to payment.`,`Pay the order on the payment service page. The order counts as paid once the payment service confirms the payment.`,`Fulfilment time: GS Coins are credited to the balance usually within a few minutes after the payment is confirmed, and no later than 3 business days.`]},{heading:`4a. How the service is provided`,paragraphs:[`The service is digital: there is no physical delivery. The Contractor credits GS Coins to your account balance on the game-scout.ru site, and you then choose which game server to support. Credited GS Coins are available at once and do not expire while the account and the service exist.`,`Server support is provided instantly: after you confirm the charge, the GS Coins are counted for the chosen server in the Support ranking, and the result is visible on the site. The Contractor does not guarantee a particular place for a server in the ranking.`]},{heading:`5. Refunds`,paragraphs:[`Below it is stated directly when money is returned and when it is not. These terms do not limit consumer rights that the law does not allow to be limited.`],list:[`We refund in full if: (a) a payment was charged twice or more for one purchase; (b) a payment went through and GS Coins were not credited or were credited in a smaller amount than paid, and this was not corrected within 3 business days; (c) the server support paid for with GS Coins was not counted or not shown in the ranking through the fault of the service.`,`We refund unused GS Coins on your application if you refuse the service (Article 32 of the Consumer Protection Law): the full paid value of the unused GS Coins is refunded; the fee of the payment service or bank is not deducted from the refund.`,`We do not refund GS Coins already spent on supporting a server and counted in the "Support" ranking: the service was rendered properly and you can see its result on the site. The exception is case (c) above.`,`We do not refund money when an account is blocked for manipulation, fraud or use of other people's payment instruments, or for payments disputed by the payer at the bank until the dispute is resolved in your favor.`,`Refund procedure. The application is submitted in writing, in one email to the address from the "Operator and contacts" section, only from the email address linked to the account. In the application state: the account name, the date and time of the payment, the amount, the order or receipt number from the payment email, the reason for the refund and the payment details (last 4 digits of the card or another method).`,`We check the application against the account's operation journal and the payment service data: whether the payment was made, how many GS Coins were credited and how many of them were used. For this we may ask for confirmation that you own the account and the payment instrument (for example, a reply to a verification email). An application without this data is accepted after you supplement it; the review period counts from receipt of all the data.`,`Term: a reply to the application within 3 business days, a decision and the refund within 10 days from receipt of the complete application (the total term is not longer than that established by law). The refund goes only by the same method and to the same details that were used for payment; refunds to other details or in cash are not made.`,`If the application is rejected, we state the reason; the refusal can be disputed by sending a claim to the same email address.`]},{heading:`6. Account blocking`,paragraphs:[`If the site rules are violated (manipulation, fraud, use of other people's payment instruments), the Contractor may restrict the account. The remaining GS Coins are refunded, except in cases of fraud and disputed payments.`]},{heading:`7. Liability`,paragraphs:[`The service is provided "as is". Within the limits allowed by law, the Contractor's liability is limited to the amount of the payment for the corresponding GS Coins.`]},{heading:`8. Personal data`,paragraphs:[`Data is processed under the personal data processing policy on the /privacy page.`]},{heading:`9. Disputes and changes`,paragraphs:[`Claims are accepted at the email address from the "Operator and contacts" section; a reply within 10 days. If the dispute is not resolved, it is considered under the legislation of the Russian Federation, and the consumer's right to choose the jurisdiction is preserved.`,`The Contractor may change the offer; for GS Coins already purchased, the version in force at the time of purchase applies.`]}],links:[{label:`GS Coins rules`,to:`/coins-rules`},{label:`Data processing policy`,to:`/privacy`}]},coinsRules:{path:`/coins-rules`,title:`GS Coins and Support Rules`,description:`How GS Coins and server support work: what is allowed, what is not, how unused units are refunded.`,sections:[{heading:`In short`,list:[`GS Coins are bought, not earned, and cannot be withdrawn. The balance and the operation journal are available in the personal account.`,`Server support: you choose a server and the number of GS Coins, and before the debit you see what place you will get in the "Support" ranking.`,`The "Votes" ranking is built only from player votes; support does not affect it.`,`We do not sell places in rankings and do not promise a result.`]},{heading:`Public name in the list of supporters`,paragraphs:[`The name you choose is shown. Unsuitable names are replaced with "Anonymous"; the support is still counted.`]},{heading:`Refunds`,list:[`We refund: a double charge; a payment went through and GS Coins were not credited or not credited in full; support was not counted through the fault of the service.`,`We refund unused GS Coins on application in the full amount paid; the payment service fee is not deducted.`,`We do not refund GS Coins spent on support if the support is counted and visible in the ranking.`,`We do not refund when an account is blocked for manipulation and fraud, or for disputed payments until the dispute is resolved.`],paragraphs:[`The application is submitted by email from the account's mailbox: the order or receipt number, date, amount and reason. We review it within 10 days and refund to the same details. The full terms are in the public offer.`]}],links:[{label:`Public offer`,to:`/offer`},{label:`User Agreement`,to:`/terms`}]}},l={updated:`29 October 2026`,path:`/about`,title:`About the project and methodology`,description:`What GameScout is, where server cards come from, how online is verified and labelled, and how the overall top is calculated.`,sections:[{heading:`What GameScout is`,paragraphs:[`GameScout (gamescout.online) is a catalog of Lineage 2, Minecraft and GTA RP (FiveM and RAGE:MP) game servers. A server card collects the version or chronicle, rates or mode, region, opening date, project links and online with the source stated.`,`Browsing the catalog and adding a server is free. The main rule of the project: every number on the site is labelled with its source and time, and whatever cannot be confirmed is not presented as fact.`]},{heading:`Where the cards come from`,paragraphs:[`Cards are compiled from public sources: official sites, pages and communities of the projects. The source and the date of the check are shown on the server page.`,`Only confirmed characteristics reach the public catalog. If a field could not be verified, it stays empty with a "not specified" note; we do not fill it with guesses.`]},{heading:`How online is verified`,paragraphs:[`Online is looked up through a chain of sources: first GameScout's own check, then the counter published by the project itself, then third-party monitoring. The status, the source and the update time are always shown next to the number; a stale number is never shown as current.`],list:[`"Verified by GameScout" (VERIFIED): we counted the players ourselves, from the player list at the server's own address or through the API and the owner's agent. A number the server merely reports about itself is not labelled this way.`,`LIVE: the server answers our check, but the player count is reported by the server itself (as in Minecraft) or not reported at all (as in Lineage 2), so it cannot be confirmed.`,`"Per the owner": a counter that the project publishes on its own site or in its API.`,`External monitoring: a number from a third-party service (for example mcsrvstat.us or BattleMetrics) with its name. Such a number is never labelled as verified.`,`OFFLINE: only with grounds, when a source reports that the server is switched off, or our check failed twice and there is nobody else to ask.`,`If no source answered, online is unknown. That is neither zero nor OFFLINE.`,`"Anomaly": a different project answers at the server's address (for example, the address was handed to another server); such data is not attached to the card until it is re-checked.`]},{heading:`Specifics of each game`,list:[`Minecraft: the server answers the standard status query, so its availability and the declared online are visible directly.`,`GTA RP (FiveM): exact online is counted only from the player list at the server's own address.`,`Lineage 2: there is no open way to learn the number of players. The availability of the login server can be checked; exact verified online is possible only through the API or the owner's agent.`]},{heading:`How the overall top is calculated`,paragraphs:[`Player votes, support and fresh online each give one third of the overall score. Values are compared within one game; missing data adds no points.`,`The separate "Votes" ranking counts player votes only. Support with GS Coins is shown separately and adds no votes.`]},{heading:`What we do not do`,list:[`We do not invent online and do not round it up.`,`We do not write reviews or votes on behalf of players.`,`We do not bypass bot protection on other people's sites: if a source is closed, the number is not shown.`,`We do not merge accounts by the email address from Google or Discord without an explicit action by the user.`]},{heading:`For server owners`,paragraphs:[`A server can be added through the catalog form. Ownership of a card is confirmed by a DNS record, a file on the project's site, through Discord or by a manual check by an administrator. Connecting the API or the agent allows showing verified online.`]},{heading:`Found a mistake?`,paragraphs:[`If a card contains wrong data, write to us at the email below and include the link to the server page. Claims of rights holders are accepted through a separate form.`]}],links:[{label:`Server catalog`,to:`/catalog`},{label:`For server owners`,to:`/owners`},{label:`For rights holders`,to:`/copyright`}]},u=n();function d({doc:n,dated:s,courtesy:l}){let d=e(),f=t()===`en`,p=s??d(`Редакция от {d}`,{d:(f?c:o).updated});a({title:i(n.title),description:i(n.description),path:n.path});let{operator:m}=f?c:o;return(0,u.jsxs)(`main`,{className:`mx-auto max-w-3xl space-y-6 px-4 py-10`,children:[(0,u.jsx)(`h1`,{className:`text-3xl font-semibold`,children:n.title}),(0,u.jsx)(`p`,{className:`text-sm text-ink-400`,children:p}),f&&l&&(0,u.jsx)(`p`,{className:`rounded-lg border border-white/10 bg-white/[0.04] px-3 py-2 text-sm text-ink-300`,role:`note`,children:d(`Courtesy translation. The Russian version is authoritative.`)}),n.sections.map(e=>(0,u.jsxs)(`section`,{className:`space-y-3`,children:[(0,u.jsx)(`h2`,{className:`text-xl font-medium`,children:e.heading}),e.paragraphs?.map(e=>(0,u.jsx)(`p`,{className:`text-ink-300`,children:i(e)},e)),e.list&&(0,u.jsx)(`ul`,{className:`list-disc space-y-2 pl-5 text-ink-300`,children:e.list.map(e=>(0,u.jsx)(`li`,{children:i(e)},e))})]},e.heading)),n.links&&(0,u.jsx)(`p`,{className:`flex flex-wrap gap-x-5`,children:n.links.map(e=>(0,u.jsx)(r,{className:`inline-flex min-h-11 items-center text-signal-400 underline`,to:e.to,children:e.label},e.to))}),(0,u.jsxs)(`section`,{className:`space-y-2 border-t border-white/8 pt-6`,children:[(0,u.jsx)(`h2`,{className:`text-xl font-medium`,children:d(`Оператор и контакты`)}),m.name&&(0,u.jsxs)(`p`,{className:`text-ink-300`,children:[d(`Оператор`),`: `,n.path===`/offer`&&`fullName`in m?m.fullName:m.name,m.inn?`, ${d(`ИНН`)} ${m.inn}`:``]}),m.address&&(0,u.jsxs)(`p`,{className:`text-ink-300`,children:[d(`Адрес`),`: `,m.address]}),(0,u.jsxs)(`p`,{className:`text-ink-300`,children:[d(`Вопросы по данным и претензии`),`: `,(0,u.jsx)(`a`,{className:`text-signal-400 underline`,href:`mailto:${m.contactEmail}`,children:m.contactEmail})]}),(0,u.jsxs)(`p`,{className:`text-sm text-ink-400`,children:[(0,u.jsx)(r,{className:`underline`,to:`/privacy`,children:d(`Политика`)}),` · `,(0,u.jsx)(r,{className:`underline`,to:`/terms`,children:d(`Соглашение`)}),` · `,(0,u.jsx)(r,{className:`underline`,to:`/copyright`,children:d(`Правообладателям`)})]})]})]})}var f=()=>t()===`en`?c:o;function p(){return(0,u.jsx)(d,{doc:f().privacy,courtesy:!0})}function m(){return(0,u.jsx)(d,{doc:f().terms,courtesy:!0})}function h(){return(0,u.jsx)(d,{doc:f().offer,courtesy:!0})}function g(){return(0,u.jsx)(d,{doc:f().coinsRules,courtesy:!0})}function _(){let n=e(),r=t()===`en`?l:s;return(0,u.jsx)(d,{doc:r,dated:n(`Обновлено {d}`,{d:r.updated})})}export{_ as About,g as CoinsRules,h as Offer,p as Privacy,m as Terms};